private void ease(DirectedEdge edgeObj) {
    int srcVertex = edgeObj.from();
    int destVertex = edgeObj.to();
    if (distTo[destVertex] > distTo[srcVertex] + edgeObj.weight()) {
        distTo[destVertex] = distTo[srcVertex] + edgeObj.weight();
        edgeTo[destVertex] = edgeObj;
        if (pq.contains(destVertex)) {
            pq.change(destVertex, distTo[destVertex]);
        } else {
            pq.insert(destVertex, distTo[destVertex]);
        }
    }
}

public Iterable<DirectedEdge> routeTo(int vertexId) {
        if (!hasRouteTo(vertexId)) return null;
        Stack<DirectedEdge> routeStack = new Stack<>();
        for (DirectedEdge edgeItem = linkTo[vertexId]; edgeItem != null; edgeItem = linkTo[edgeItem.from()])
            routeStack.push(edgeItem);
        return routeStack;
    }

